SELECT CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(AVG(quantity), 2) AS avg_quantity, SUM(quantity) AS total_quantity, MAX(quantity) - MIN(quantity) AS quantity_range FROM order_items WHERE order_id IN (20, 31) AND product_id = 10 AND unit_price BETWEEN 150 AND 260 GROUP BY 1 ORDER BY unit_price_bucket, quantity_range LIMIT 3;
